// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {EtherLotto} from "../src/EtherLotto.sol";

contract InvMutTest is Test {
    EtherLotto c;
    function setUp() public { c = new EtherLotto(); }

    function testFuzz_property(address caller) public {
        vm.assume(caller != address(0));

        uint256 potBefore = c.pot();

        uint256 ticket = 10;
        vm.deal(caller, ticket);
        vm.prank(caller);
        c.play{value: ticket}();

        uint256 potAfter = c.pot();

        assertTrue(potAfter >= potBefore);
    }
}
